// Считаем «завтра» по Уфе (UTC+5)
// n8n в Москве (UTC+3), поэтому Уфа = МСК + 2 часа
const now = new Date();
const msk = new Date(now.getTime() + 3 * 60 * 60 * 1000);
const ufa = new Date(msk.getTime() + 2 * 60 * 60 * 1000);
const tomorrow = new Date(ufa.getTime() + 24 * 60 * 60 * 1000);

const day = tomorrow.getUTCDate();
const month = tomorrow.getUTCMonth();
const year = tomorrow.getUTCFullYear();

const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];

return [{
  json: {
    tomorrowISO: year + '-' + String(month + 1).padStart(2, '0') + '-' + String(day).padStart(2, '0'),
    tomorrowHuman: day + ' ' + months[month] + ' ' + year
  }
}];

const items = $input.all();
const tomorrowReadable = $('Get Tomorrow (Уфа)').item.json.tomorrowHuman;

let listText = '📅 Завтра, ' + tomorrowReadable + ':\n\n';
if (items.length === 0) {
  listText += 'Записей нет. Отдыхай! 🌸';
} else {
  for (const item of items) {
    const phoneStr = item.json.phone ? ` (${item.json.phone})` : '';
    listText += '⏰ ' + item.json.time + ' — ' + item.json.clientName + phoneStr + '\n';
  }
}

let templates = '';
if (items.length > 0) {
  templates = '\n\n---\n\n✉️ ШАБЛОНЫ ДЛЯ КЛИЕНТОВ:\n';
  for (const item of items) {
    const phoneStr = item.json.phone ? ` (${item.json.phone})` : '';
    templates += '\n👤 ' + item.json.clientName + phoneStr + ' (' + item.json.time + '):\n';
    templates += 'Добрый вечер 🌸\n';
    templates += 'Жду вас ' + tomorrowReadable + ', ' + item.json.time + '\n';
    templates += 'Адрес: Рахимьяна Насырова 4 кВ 93, отдельный вход\n';
    templates += 'Оплата наличными 💵.\n';
    templates += '---\n';
  }
}

return [{ json: { message: listText + templates } }];
